import AVFoundation
import Foundation

// Read the luma barcode generated by smart_trim.py with the native movie reader.
@main
struct DecodeFrameIDs {
    static func main() async throws {
        let asset = AVURLAsset(url: URL(fileURLWithPath: CommandLine.arguments[1]))
        guard let track = try await asset.loadTracks(withMediaType: .video).first else {
            throw CocoaError(.fileReadCorruptFile)
        }
        let reader = try AVAssetReader(asset: asset)
        if CommandLine.arguments.count == 3, let offset = Int64(CommandLine.arguments[2]) {
            reader.timeRange = CMTimeRange(start: CMTime(value: offset, timescale: 25), end: .positiveInfinity)
        }
        let output = AVAssetReaderTrackOutput(track: track, outputSettings: [
            kCVPixelBufferPixelFormatTypeKey as String: kCVPixelFormatType_420YpCbCr8BiPlanarVideoRange
        ])
        reader.add(output)
        guard reader.startReading() else { throw reader.error ?? CocoaError(.fileReadCorruptFile) }
        var ids = Data()
        while let sample = output.copyNextSampleBuffer() {
            guard let image = sample.imageBuffer,
                  CVPixelBufferGetWidth(image) >= 128, CVPixelBufferGetHeight(image) >= 16,
                  CVPixelBufferLockBaseAddress(image, .readOnly) == kCVReturnSuccess else {
                throw CocoaError(.fileReadCorruptFile)
            }
            defer { CVPixelBufferUnlockBaseAddress(image, .readOnly) }
            guard let luma = CVPixelBufferGetBaseAddressOfPlane(image, 0) else {
                throw CocoaError(.fileReadCorruptFile)
            }
            let row = luma.advanced(by: 8 * CVPixelBufferGetBytesPerRowOfPlane(image, 0))
                .assumingMemoryBound(to: UInt8.self)
            var id: UInt8 = 0
            for bit in 0..<8 where row[bit * 16 + 8] > 120 { id |= 1 << bit }
            ids.append(id)
        }
        guard reader.status == .completed else { throw reader.error ?? CocoaError(.fileReadCorruptFile) }
        try FileHandle.standardOutput.write(contentsOf: ids)
    }
}
